const upsertClassAttendance = `-- name: UpsertClassAttendance :exec
INSERT INTO class_attendance (class_id, student_id, status, source, marked_by)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (class_id, student_id) DO UPDATE
SET status = EXCLUDED.status, source = EXCLUDED.source, marked_by = EXCLUDED.marked_by, marked_at = now()
`

type UpsertClassAttendanceParams struct {
	ClassID   uuid.UUID  `json:"class_id"`
	StudentID uuid.UUID  `json:"student_id"`
	Status    string     `json:"status"`
	Source    string     `json:"source"`
	MarkedBy  *uuid.UUID `json:"marked_by"`
}

func (q *Queries) UpsertClassAttendance(ctx context.Context, arg UpsertClassAttendanceParams) error {
	_, err := q.db.Exec(ctx, upsertClassAttendance,
		arg.ClassID,
		arg.StudentID,
		arg.Status,
		arg.Source,
		arg.MarkedBy,
	)
	return err
}

const upsertEnrollment = `-- name: UpsertEnrollment :one
INSERT INTO enrollments (student_id, course_id, batch_id, assigned_by)
VALUES ($1, $2, $3, $4)
ON CONFLICT (student_id, course_id) DO UPDATE
SET batch_id = EXCLUDED.batch_id,
    status = CASE WHEN enrollments.status = 'suspended' THEN 'active' ELSE enrollments.status END
RETURNING id, student_id, course_id, batch_id, status, assigned_by, enrolled_at, completed_at, version_id
`

type UpsertEnrollmentParams struct {
	StudentID  uuid.UUID  `json:"student_id"`
	CourseID   uuid.UUID  `json:"course_id"`
	BatchID    *uuid.UUID `json:"batch_id"`
	AssignedBy *uuid.UUID `json:"assigned_by"`
}

func (q *Queries) UpsertEnrollment(ctx context.Context, arg UpsertEnrollmentParams) (Enrollment, error) {
	row := q.db.QueryRow(ctx, upsertEnrollment,
		arg.StudentID,
		arg.CourseID,
		arg.BatchID,
		arg.AssignedBy,
	)
	var i Enrollment
	err := row.Scan(
		&i.ID,
		&i.StudentID,
		&i.CourseID,
		&i.BatchID,
		&i.Status,
		&i.AssignedBy,
		&i.EnrolledAt,
		&i.CompletedAt,
		&i.VersionID,
	)
	return i, err
}
